import { h as seriesOf, m as seqOf, u as orderRateBuckets, v as untaxedSales } from "./report-logic-CSVRdBz3.js";
import { c as gstModeOf, l as placeOfSupply } from "./AppInstall-PC3rCyrK.js";
//#region src/lib/gstr1.ts
/**
* GSTR-1 workbook from POS bills, laid out like the GST portal's offline
* tool sheets (b2b, b2cs, hsn, docs) so rows can be pasted straight in,
* plus a Summary and the Table 14 sales made through Swiggy/Zomato.
*/
var r2 = (n) => Math.round(n * 100) / 100;
var MONTHS = [
	"Jan",
	"Feb",
	"Mar",
	"Apr",
	"May",
	"Jun",
	"Jul",
	"Aug",
	"Sep",
	"Oct",
	"Nov",
	"Dec"
];
/** GST portal date style: 17-Oct-2026 */
function gstDate(at) {
	const d = new Date(at);
	return `${String(d.getDate()).padStart(2, "0")}-${MONTHS[d.getMonth()]}-${d.getFullYear()}`;
}
var GSTIN_RE = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/;
var isB2b = (o) => GSTIN_RE.test((o.customer?.gstin ?? "").trim().toUpperCase());
function gstr1Workbook(orders, settings, period) {
	const pos = placeOfSupply(settings.gstin);
	const settled = orders.filter((o) => o.status === "settled").sort((a, b) => a.createdAt - b.createdAt);
	const regular = gstModeOf(settings) === "regular";
	const b2bRows = [];
	let b2bTaxable = 0;
	let tax = 0;
	const b2bInvoices = /* @__PURE__ */ new Set();
	for (const o of settled.filter(isB2b)) for (const [rate, value] of [...orderRateBuckets(o)].sort(([a], [b]) => a - b)) {
		b2bRows.push([
			o.customer.gstin.trim().toUpperCase(),
			o.customer?.name ?? "",
			o.billNo,
			gstDate(o.createdAt),
			o.total,
			pos,
			"N",
			"",
			"Regular B2B",
			"",
			rate,
			r2(value),
			0
		]);
		b2bTaxable += value;
		tax += value * rate / 100;
		b2bInvoices.add(o.billNo);
	}
	const b2cs = /* @__PURE__ */ new Map();
	for (const o of settled.filter((x) => !isB2b(x))) for (const [rate, value] of orderRateBuckets(o)) b2cs.set(rate, (b2cs.get(rate) ?? 0) + value);
	const b2csRows = [...b2cs].sort(([a], [b]) => a - b).map(([rate, value]) => {
		tax += value * rate / 100;
		return [
			"OE",
			pos,
			"",
			rate,
			r2(value),
			0,
			""
		];
	});
	const b2csTaxable = [...b2cs.values()].reduce((s, v) => s + v, 0);
	const sac = settings.sac || "996331";
	const hsnRows = (subset) => {
		const byRate = /* @__PURE__ */ new Map();
		for (const o of subset) {
			const buckets = orderRateBuckets(o);
			const billTaxable = [...buckets.values()].reduce((s, v) => s + v, 0);
			for (const [rate, value] of buckets) {
				const row = byRate.get(rate) ?? {
					taxable: 0,
					value: 0
				};
				row.taxable += value;
				row.value += billTaxable > 0 ? o.total * (value / billTaxable) : 0;
				byRate.set(rate, row);
			}
		}
		return [...byRate].sort(([a], [b]) => a - b).map(([rate, v]) => {
			const half = r2(v.taxable * rate / 200);
			return [
				sac,
				"Restaurant service",
				"NA",
				0,
				r2(v.value),
				rate,
				r2(v.taxable),
				0,
				half,
				half,
				0
			];
		});
	};
	const issued = orders.filter((o) => (o.status === "settled" || o.status === "void") && o.billNo);
	const series = /* @__PURE__ */ new Map();
	for (const o of issued) series.set(seriesOf(o.billNo), [...series.get(seriesOf(o.billNo)) ?? [], o]);
	const docRows = [...series].sort(([a], [b]) => a.localeCompare(b)).map(([, list]) => {
		const sorted = [...list].sort((a, b) => seqOf(a.billNo) - seqOf(b.billNo));
		const unique = new Map(sorted.map((o) => [o.billNo, o]));
		const cancelled = [...unique.values()].filter((o) => o.status === "void").length;
		return [
			regular ? "Invoices for outward supply" : "Bill of supply",
			sorted[0].billNo,
			sorted[sorted.length - 1].billNo,
			unique.size,
			cancelled
		];
	});
	const eco = /* @__PURE__ */ new Map();
	for (const o of settled) if ((o.orderType === "swiggy" || o.orderType === "zomato") && o.tax?.exempt) {
		const name = o.orderType === "swiggy" ? "Swiggy (Bundl Technologies)" : "Zomato";
		eco.set(name, (eco.get(name) ?? 0) + (o.taxable ?? o.total));
	}
	const ecoRows = [...eco].map(([name, value]) => [
		"Restaurant service, tax paid by operator u/s 9(5)",
		name,
		"",
		r2(value)
	]);
	const untaxed = untaxedSales(orders);
	const totals = {
		b2bInvoices: b2bInvoices.size,
		b2bTaxable: r2(b2bTaxable),
		b2csTaxable: r2(b2csTaxable),
		tax: r2(tax),
		aggregatorValue: untaxed.aggregator,
		untaxedValue: untaxed.other,
		documents: docRows.reduce((s, r) => s + Number(r[3]), 0),
		cancelled: docRows.reduce((s, r) => s + Number(r[4]), 0)
	};
	return {
		sheets: [
			{
				name: "Summary",
				title: `GSTR-1 — ${settings.legalName || settings.name || "Restaurant"}`,
				subtitle: `GSTIN ${settings.gstin || "not set"}, ${period}. Place of supply ${pos}.`,
				columns: [
					{
						header: "Section",
						width: 46
					},
					{
						header: "Invoices / rows",
						format: "int"
					},
					{
						header: "Taxable value",
						format: "inr"
					},
					{
						header: "CGST + SGST",
						format: "inr"
					}
				],
				rows: [
					[
						"4A — B2B invoices (guests with a GSTIN)",
						b2bInvoices.size,
						r2(b2bTaxable),
						r2(b2bRows.reduce((s, r) => s + Number(r[11]) * Number(r[10]) / 100, 0))
					],
					[
						"7 — B2C small (all other bills)",
						b2csRows.length,
						r2(b2csTaxable),
						r2(b2csRows.reduce((s, r) => s + Number(r[4]) * Number(r[3]) / 100, 0))
					],
					[
						"14(b) — through Swiggy/Zomato, tax paid by them",
						ecoRows.length,
						totals.aggregatorValue,
						0
					],
					[
						"Bills with no GST (composition / unregistered)",
						null,
						totals.untaxedValue,
						0
					],
					[
						"13 — Documents issued",
						totals.documents,
						null,
						null
					],
					[
						"13 — of which cancelled",
						totals.cancelled,
						null,
						null
					]
				],
				notes: [
					"Prepared by XTSY POS from synced bills. Check every figure with your accountant before filing.",
					"b2b, b2cs, hsn(b2b), hsn(b2c) and docs sheets use the GST offline tool's column order; paste rows below its headers.",
					"Restaurant service is intra-state (CGST + SGST). Rates come from each dish's GST rate."
				]
			},
			{
				name: "b2b",
				columns: [
					{
						header: "GSTIN/UIN of Recipient",
						width: 18
					},
					{
						header: "Receiver Name",
						width: 24
					},
					{
						header: "Invoice Number",
						width: 16
					},
					{
						header: "Invoice date",
						width: 13
					},
					{
						header: "Invoice Value",
						format: "inr"
					},
					{
						header: "Place Of Supply",
						width: 16
					},
					{ header: "Reverse Charge" },
					{ header: "Applicable % of Tax Rate" },
					{
						header: "Invoice Type",
						width: 14
					},
					{ header: "E-Commerce GSTIN" },
					{
						header: "Rate",
						format: "int"
					},
					{
						header: "Taxable Value",
						format: "inr"
					},
					{
						header: "Cess Amount",
						format: "inr"
					}
				],
				rows: b2bRows
			},
			{
				name: "b2cs",
				columns: [
					{ header: "Type" },
					{
						header: "Place Of Supply",
						width: 16
					},
					{ header: "Applicable % of Tax Rate" },
					{
						header: "Rate",
						format: "int"
					},
					{
						header: "Taxable Value",
						format: "inr"
					},
					{
						header: "Cess Amount",
						format: "inr"
					},
					{ header: "E-Commerce GSTIN" }
				],
				rows: b2csRows
			},
			...["b2b", "b2c"].map((kind) => ({
				name: `hsn(${kind})`,
				columns: [
					{ header: "HSN" },
					{
						header: "Description",
						width: 20
					},
					{ header: "UQC" },
					{
						header: "Total Quantity",
						format: "int"
					},
					{
						header: "Total Value",
						format: "inr"
					},
					{
						header: "Rate",
						format: "int"
					},
					{
						header: "Taxable Value",
						format: "inr"
					},
					{
						header: "Integrated Tax Amount",
						format: "inr"
					},
					{
						header: "Central Tax Amount",
						format: "inr"
					},
					{
						header: "State/UT Tax Amount",
						format: "inr"
					},
					{
						header: "Cess Amount",
						format: "inr"
					}
				],
				rows: hsnRows(settled.filter((o) => kind === "b2b" ? isB2b(o) : !isB2b(o)))
			})),
			{
				name: "docs",
				columns: [
					{
						header: "Nature of Document",
						width: 30
					},
					{
						header: "Sr. No. From",
						width: 16
					},
					{
						header: "Sr. No. To",
						width: 16
					},
					{
						header: "Total Number",
						format: "int"
					},
					{
						header: "Cancelled",
						format: "int"
					}
				],
				rows: docRows
			},
			{
				name: "eco 9(5)",
				title: "Table 14(b) — supplies through e-commerce operators liable to pay tax u/s 9(5)",
				subtitle: "Fill in each operator's GSTIN for your state.",
				columns: [
					{
						header: "Nature of supply",
						width: 46
					},
					{
						header: "E-commerce operator",
						width: 28
					},
					{
						header: "GSTIN of operator",
						width: 18
					},
					{
						header: "Net value of supplies",
						format: "inr"
					}
				],
				rows: ecoRows
			}
		],
		totals
	};
}
//#endregion
export { gstr1Workbook as t };
